    <script>
        (() => { const panel=document.getElementById('accountPanel'), register=document.getElementById('accountRegister'), login=document.getElementById('accountLogin'); if(!panel||!register||!login)return; const choice=document.createElement('div'); choice.id='accountChoice'; choice.style.padding='8px 0 18px'; choice.innerHTML='<h2>Você já possui cadastro no cardapiodigitalbh?</h2><p style="color:var(--muted);margin-top:8px">Escolha uma opção para continuar o envio do seu pedido.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:20px"><button id="chooseAccountLogin" class="checkout" type="button" style="margin-top:0">Sim</button><button id="chooseAccountRegister" class="checkout" type="button" style="margin-top:0;background:var(--brand-dark)">Não</button></div>'; register.parentNode.insertBefore(choice,register); register.hidden=true; document.getElementById('chooseAccountLogin').addEventListener('click',()=>{choice.hidden=true;register.hidden=true;login.hidden=false;}); document.getElementById('chooseAccountRegister').addEventListener('click',()=>{choice.hidden=true;login.hidden=true;register.hidden=false;}); const reset=()=>{choice.hidden=false;register.hidden=true;login.hidden=true;}; window.resetConsumerAccountChoice=reset; document.getElementById('checkout').addEventListener('click',()=>{if(!window.consumer)reset();},true); })();
        (() => {
            const cart = new Map(JSON.parse(localStorage.getItem('cardapiodigitalbh_cart') || '[]').map(item => [item.key, item]));
            const money = value => new Intl.NumberFormat('pt-BR', {style:'currency', currency:'BRL'}).format(value);
            const button = document.getElementById('cartButton');
            const panel = document.getElementById('cartPanel');
            const lines = document.getElementById('cartLines');
            const notice = document.getElementById('notice');
            const checkout = document.getElementById('checkout');
            const customPanel = document.getElementById('customPanel');
            const customGroups = document.getElementById('customGroups');
            const customError = document.getElementById('customError');
            const accountPanel = document.getElementById('accountPanel');
            let consumer = @json($publicConsumerData);
            let customizing = null;
            let coordinates = null;
            const escapeHtml = value => { const div = document.createElement('div'); div.textContent = value; return div.innerHTML; };

            function render() {
                const entries = [...cart.values()];
                const count = entries.reduce((sum, item) => sum + item.quantity, 0);
                const total = entries.reduce((sum, item) => sum + item.price * item.quantity, 0);
                button.classList.toggle('visible', count > 0);
                document.getElementById('cartCount').textContent = count + (count === 1 ? ' item' : ' itens');
                document.getElementById('cartTotal').textContent = money(total);
                lines.innerHTML = entries.map(item => `<div class="cart-line"><div><strong>${escapeHtml(item.name)}</strong>${item.optionNames.length ? `<small style="display:block;color:var(--muted)">${escapeHtml(item.optionNames.join(', '))}</small>` : ''}<div>${money(item.price * item.quantity)}</div></div><div class="cart-actions"><button type="button" class="remove-item" data-remove="${item.key}">Remover</button><div class="qty"><button type="button" data-less="${item.key}" aria-label="Diminuir quantidade de ${escapeHtml(item.name)}">−</button><b>${item.quantity}</b><button type="button" data-more="${item.key}" aria-label="Aumentar quantidade de ${escapeHtml(item.name)}">+</button></div></div></div>`).join('');
                document.getElementById('cartSummary').innerHTML = entries.length ? `${entries.map(item => `<div class="cart-summary-line">${item.image ? `<img class="cart-summary-thumb" src="${escapeHtml(item.image)}" alt="" loading="lazy">` : '<span class="cart-summary-thumb cart-summary-thumb-placeholder" aria-hidden="true"></span>'}<strong class="cart-summary-title-item">${escapeHtml(item.name)}</strong><div class="cart-summary-main"><span class="cart-summary-subtotal">Subtotal: ${money(item.price * item.quantity)}</span><div class="cart-summary-actions"><span class="quantity-control"><input type="number" min="1" max="99" value="${item.quantity}" data-summary-qty="${item.key}" aria-label="Quantidade de ${escapeHtml(item.name)}"><span class="quantity-stepper"><button type="button" class="quantity-step" data-summary-more="${item.key}" aria-label="Aumentar quantidade">+</button><button type="button" class="quantity-step" data-summary-less="${item.key}" aria-label="Diminuir quantidade">−</button></span></span><button type="button" class="summary-remove" data-summary-remove="${item.key}">Remover</button></div></div></div>`).join('')}<div class="cart-total-row"><span>Total do pedido</span><strong>${money(total)}</strong></div>` : '';
                window.dispatchEvent(new Event('cardapiodigitalbh:cart-updated'));
            }
            function addItem(product, selected = [], quantity = 1) { const optionIds = selected.map(option => option.id).sort((a,b)=>a-b); const key = product.id+'-'+optionIds.join('-'); const price = product.price + selected.reduce((sum, option) => sum + option.price, 0); const current = cart.get(key) || {key,id:product.id,name:product.name,price,optionIds,optionNames:selected.map(option=>option.name),image:product.image || null,quantity:0}; current.image = current.image || product.image || null; current.quantity += Math.max(1, Math.min(99, Number(quantity) || 1)); cart.set(key,current); localStorage.setItem('cardapiodigitalbh_cart', JSON.stringify([...cart.values()])); render(); }
            let customQuantity = 1;
            function openCustomizer(product, quantity = 1) { customizing=product; customQuantity=quantity; document.getElementById('customTitle').textContent=product.name; customError.style.display='none'; customGroups.innerHTML=product.groups.map(group=>`<section style="margin-top:18px;padding-top:16px;border-top:1px solid var(--line)" data-group="${group.id}" data-min="${group.minimum}" data-max="${group.maximum}"><h3 style="margin:0 0 4px">${escapeHtml(group.name)}</h3><small style="color:var(--muted)">${group.minimum ? `Escolha no mínimo ${group.minimum}` : 'Opcional'} · máximo ${group.maximum}</small>${group.options.map(option=>`<label class="custom-option"><input type="checkbox" value="${option.id}"><span class="custom-option-check" aria-hidden="true"><svg viewBox="0 0 16 16"><path d="M3.4 8.4l2.6 2.6 6-6"></path></svg></span><span class="custom-option-copy"><strong>${escapeHtml(option.name)}</strong>${option.description ? `<small>${escapeHtml(option.description)}</small>` : ''}</span><span class="custom-option-price">${option.price ? '+ '+money(option.price) : 'Grátis'}</span></label>`).join('')}</section>`).join(''); customPanel.classList.add('open'); }
            let optionSelectionSequence=0;
            customGroups.addEventListener('change',event=>{ const input=event.target.closest('input[type="checkbox"]'); if(!input||!input.checked)return; input.dataset.selectedAt=String(++optionSelectionSequence); const group=input.closest('[data-group]'); const maximum=Number(group.dataset.max); const checked=[...group.querySelectorAll('input:checked')]; if(checked.length>maximum){ checked.filter(item=>item!==input).sort((a,b)=>Number(a.dataset.selectedAt||0)-Number(b.dataset.selectedAt||0))[0].checked=false; } customError.style.display='none'; });
            function equalizeListDescriptions(){ if(!document.querySelector('.catalog-list')) return; document.querySelectorAll('.catalog-list .product-description').forEach(description=>{description.style.minHeight='0px';}); const descriptions=[...document.querySelectorAll('.catalog-list .product-description')]; const height=descriptions.reduce((maximum,description)=>Math.max(maximum,description.scrollHeight),0); descriptions.forEach(description=>{description.style.minHeight=height+'px';}); }
            window.addEventListener('resize',equalizeListDescriptions,{passive:true});
            requestAnimationFrame(equalizeListDescriptions);
            document.querySelectorAll('[data-product]').forEach(el => el.addEventListener('click', () => { const product=JSON.parse(el.dataset.product); const quantityInput=el.closest('.product-body')?.querySelector('[data-product-quantity]'); const quantity=Math.max(1,Math.min(99,Number(quantityInput?.value)||1)); if(quantityInput)quantityInput.value=quantity; product.groups.length ? openCustomizer(product,quantity) : addItem(product,[],quantity); }));
            document.addEventListener('click', event => { const action=event.target.closest('[data-quantity-action]'); if(!action)return; event.preventDefault(); event.stopPropagation(); const input=action.closest('.quantity-control')?.querySelector('input'); if(!input)return; const value=Math.max(1,Math.min(99,(Number(input.value)||1)+(action.dataset.quantityAction==='more'?1:-1))); input.value=value; });
            document.querySelectorAll('.product-track').forEach(track=>{const carousel=track.closest('.product-carousel');const previous=carousel?.querySelector('[data-slide="prev"]');const next=carousel?.querySelector('[data-slide="next"]');const updateControls=()=>{const maximum=Math.max(0,track.scrollWidth-track.clientWidth);const expanded=carousel?.classList.contains('expanded');if(previous)previous.hidden=expanded||track.scrollLeft<=2;if(next)next.hidden=expanded||track.scrollLeft>=maximum-2;};previous?.addEventListener('click',()=>track.scrollBy({left:-Math.round(track.clientWidth*.82),behavior:'smooth'}));next?.addEventListener('click',()=>track.scrollBy({left:Math.round(track.clientWidth*.82),behavior:'smooth'}));track.addEventListener('scroll',updateControls,{passive:true});new ResizeObserver(updateControls).observe(track);requestAnimationFrame(updateControls);});
            document.querySelectorAll('[data-expand-category]').forEach(button=>button.addEventListener('click',()=>{const carousel=button.closest('[data-category]').querySelector('.product-carousel');const expanded=carousel.classList.toggle('expanded');button.setAttribute('aria-expanded',String(expanded));button.textContent=expanded?'Recolher ←':'Ver tudo →';if(!expanded)carousel.querySelector('.product-track').scrollTo({left:0,behavior:'smooth'});carousel.querySelector('.product-track').dispatchEvent(new Event('scroll'));}));
            const search=document.getElementById('productSearch');
            if(search){search.addEventListener('input',()=>{const term=search.value.toLocaleLowerCase('pt-BR').trim();document.querySelectorAll('[data-category]').forEach(category=>{let visible=0;category.querySelectorAll('[data-product-card]').forEach(card=>{const match=!term||card.dataset.search.toLocaleLowerCase('pt-BR').includes(term);card.classList.toggle('filtered-out',!match);if(match)visible++;});category.classList.toggle('filtered-out',visible===0);});});const requestedSearch=new URLSearchParams(location.search).get('busca');if(requestedSearch){search.value=requestedSearch;search.dispatchEvent(new Event('input'));}}
            const selectedCategoryRail=document.getElementById('selectedCategoryRail');
            const chooseCategory=choice=>{const all=choice==='all';document.querySelector('main.wrap')?.classList.toggle('category-selected',!all);document.querySelectorAll('[data-category]').forEach(section=>section.classList.toggle('selection-hidden',!all&&section.id!==`categoria-${choice}`));document.querySelectorAll('#selectedCategoryRail [data-category-choice]').forEach(button=>button.classList.toggle('active',button.dataset.categoryChoice===choice));if(!all){document.getElementById(`categoria-${choice}`)?.scrollIntoView({behavior:'smooth',block:'start'});}else{document.getElementById('inicio')?.scrollIntoView({behavior:'smooth',block:'start'});}};
            if(selectedCategoryRail){document.querySelectorAll('#selectedCategoryRail [data-category-choice]').forEach(button=>button.addEventListener('click',()=>chooseCategory(button.dataset.categoryChoice)));}
            const requestedCategory=new URLSearchParams(location.search).get('categoria');
            if(requestedCategory && document.getElementById(`categoria-${requestedCategory}`)){requestAnimationFrame(()=>chooseCategory(requestedCategory));}
            const requestedProduct=new URLSearchParams(location.search).get('produto');
            if(requestedProduct){const requestedButton=[...document.querySelectorAll('[data-product]')].find(element=>String(JSON.parse(element.dataset.product).id)===requestedProduct);if(requestedButton){requestedButton.click();history.replaceState({},'',location.pathname);}}
            document.getElementById('confirmCustom').addEventListener('click',()=>{ const selected=[]; for(const groupElement of customGroups.querySelectorAll('[data-group]')){ const checked=[...groupElement.querySelectorAll('input:checked')]; const min=Number(groupElement.dataset.min),max=Number(groupElement.dataset.max); if(checked.length<min||checked.length>max){ customError.textContent=`Revise as escolhas de ${groupElement.querySelector('h3').textContent}.`;customError.style.display='block';return;} checked.forEach(input=>{const group=customizing.groups.find(group=>group.id===Number(groupElement.dataset.group));selected.push(group.options.find(option=>option.id===Number(input.value)));}); } addItem(customizing,selected,customQuantity); customPanel.classList.remove('open'); });
            document.getElementById('closeCustom').addEventListener('click',()=>customPanel.classList.remove('open'));
            customPanel.addEventListener('click',event=>{if(event.target===customPanel)customPanel.classList.remove('open')});
            lines.addEventListener('click', event => { const removeKey=event.target.dataset.remove; if(removeKey&&cart.has(removeKey)){cart.delete(removeKey);localStorage.setItem('cardapiodigitalbh_cart',JSON.stringify([...cart.values()]));render();return;} const key = event.target.dataset.less || event.target.dataset.more; if (!key || !cart.has(key)) return; const item = cart.get(key); item.quantity += event.target.dataset.more ? 1 : -1; item.quantity > 0 ? cart.set(key, item) : cart.delete(key); localStorage.setItem('cardapiodigitalbh_cart',JSON.stringify([...cart.values()])); render(); });
            document.getElementById('cartSummary').addEventListener('click', event => { const removeKey=event.target.dataset.summaryRemove; const key=removeKey||event.target.dataset.summaryLess||event.target.dataset.summaryMore; if(!key||!cart.has(key))return; if(removeKey){cart.delete(key);}else{const item=cart.get(key);item.quantity += event.target.dataset.summaryMore ? 1 : -1;item.quantity=Math.max(1,Math.min(99,item.quantity));cart.set(key,item);}localStorage.setItem('cardapiodigitalbh_cart',JSON.stringify([...cart.values()]));render(); });
            document.getElementById('cartSummary').addEventListener('change', event => { const key=event.target.dataset.summaryQty; if(!key||!cart.has(key))return; const item=cart.get(key); item.quantity=Math.max(1,Math.min(99,Number(event.target.value)||1)); cart.set(key,item); localStorage.setItem('cardapiodigitalbh_cart',JSON.stringify([...cart.values()])); render(); });
            button.addEventListener('click', () => panel.classList.add('open'));
            document.getElementById('closeCart').addEventListener('click', () => panel.classList.remove('open'));
            panel.addEventListener('click', event => { if (event.target === panel) panel.classList.remove('open'); });
            if (new URLSearchParams(location.search).get('abrir') === 'pedido') { requestAnimationFrame(() => panel.classList.add('open')); }
            const channel = document.getElementById('serviceChannel');
            const deliveryFields = document.getElementById('deliveryFields');
            if (channel && deliveryFields) { const toggleDelivery = () => deliveryFields.style.display = channel.value === 'delivery' ? 'block' : 'none'; channel.addEventListener('change', toggleDelivery); toggleDelivery(); }
            const paymentMethod = document.getElementById('paymentMethod');
            const changeFor = document.getElementById('changeFor');
            const changeForWrap = document.getElementById('changeForWrap');
            if (paymentMethod && changeFor && changeForWrap) { const toggleChangeFor = () => { const isCash = paymentMethod.value === 'cash'; changeForWrap.style.display = isCash ? 'block' : 'none'; if (!isCash) changeFor.value = ''; }; paymentMethod.addEventListener('change', toggleChangeFor); toggleChangeFor(); }
            const formatPhone = value => { let digits=String(value||'').replace(/\D/g,''); if(digits.startsWith('55') && digits.length>11) digits=digits.slice(2); digits=digits.slice(0,11); if(digits.length<=2)return digits.length?'('+digits:digits; if(digits.length<=6)return '('+digits.slice(0,2)+') '+digits.slice(2); if(digits.length<=10)return '('+digits.slice(0,2)+') '+digits.slice(2,6)+'-'+digits.slice(6); return '('+digits.slice(0,2)+') '+digits.slice(2,7)+'-'+digits.slice(7); };
            const attachPhoneMask = id => { const input=document.getElementById(id); if(!input)return; input.addEventListener('input',()=>{input.value=formatPhone(input.value);}); input.value=formatPhone(input.value); };
            attachPhoneMask('accountPhone'); attachPhoneMask('loginPhone'); attachPhoneMask('customerPhone');
            const accountValue = field => document.getElementById('account'+field)?.value || '';
            const showAccountError = (id, message) => { const target=document.getElementById(id); target.textContent=message; target.style.display='block'; };
            const hydrateConsumer = data => { consumer=data; const address=data.address||{}; const customerName=document.getElementById('customerName'); const customerPhone=document.getElementById('customerPhone'); if(customerName)customerName.value=data.name||''; if(customerPhone)customerPhone.value=formatPhone(data.phone?.replace(/^55/,'')||''); const fields={PostalCode:'postal_code',Street:'street',Number:'number',Neighborhood:'neighborhood',City:'city',State:'state',Complement:'complement',Reference:'reference'}; Object.entries(fields).forEach(([input,key])=>{const target=document.getElementById(input.charAt(0).toLowerCase()+input.slice(1));if(target&&address[key])target.value=address[key];}); };
            const accountRequest = async (url, body, noticeId) => { const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify(body)}); const data=await response.json(); if(!response.ok)throw new Error(Object.values(data.errors||{})[0]?.[0]||data.message||'Não foi possível concluir esta ação.'); document.getElementById(noticeId).style.display='none'; return data; };
            const accountPostalCode=document.getElementById('accountPostalCode');
            const lookupCep = async (input, ids) => { const cep=input.value.replace(/\D/g,''); if(cep.length!==8)return; input.value=cep.slice(0,5)+'-'+cep.slice(5); try { const data=await fetch('https://viacep.com.br/ws/'+cep+'/json/').then(response=>response.json()); if(data.erro){showAccountError('accountNotice','Não encontramos este CEP. Preencha o endereço manualmente.');return;} document.getElementById(ids.street).value=data.logradouro||'';document.getElementById(ids.neighborhood).value=data.bairro||'';document.getElementById(ids.city).value=data.localidade||'';document.getElementById(ids.state).value=data.uf||''; } catch (_) { if(input===accountPostalCode)showAccountError('accountNotice','Não foi possível consultar o CEP agora. Você pode preencher o endereço manualmente.'); } };
            if(accountPostalCode)accountPostalCode.addEventListener('input',()=>lookupCep(accountPostalCode,{street:'accountStreet',neighborhood:'accountNeighborhood',city:'accountCity',state:'accountState'}));
            document.getElementById('closeAccount').addEventListener('click',()=>{accountPanel.classList.remove('open');checkout.disabled=false;});
            document.getElementById('showAccountLogin').addEventListener('click',()=>{document.getElementById('accountRegister').hidden=true;document.getElementById('accountLogin').hidden=false;});
            document.getElementById('showAccountRegister').addEventListener('click',()=>{document.getElementById('accountLogin').hidden=true;document.getElementById('accountRegister').hidden=false;});
            document.getElementById('registerConsumer').addEventListener('click',async()=>{try{const phoneDigits=accountValue('Phone').replace(/\D/g,'');if(![10,11].includes(phoneDigits.length))throw new Error('Informe um telefone válido com DDD.');const data=await accountRequest(@json(route('public.consumer.register',['subdomain'=>$venue->subdomain])),{name:accountValue('Name'),phone:accountValue('Phone'),email:accountValue('Email'),password:accountValue('Password'),password_confirmation:accountValue('PasswordConfirmation'),postal_code:accountValue('PostalCode'),street:accountValue('Street'),number:accountValue('Number'),neighborhood:accountValue('Neighborhood'),city:accountValue('City'),state:accountValue('State'),complement:accountValue('Complement'),reference:accountValue('Reference')},'accountNotice');hydrateConsumer(data.consumer);accountPanel.classList.remove('open');await submitOrder();}catch(error){showAccountError('accountNotice',error.message);}});
            document.getElementById('loginConsumer').addEventListener('click',async()=>{try{const data=await accountRequest(@json(route('public.consumer.login',['subdomain'=>$venue->subdomain])),{phone:document.getElementById('loginPhone').value,password:document.getElementById('loginPassword').value},'loginNotice');hydrateConsumer(data.consumer);accountPanel.classList.remove('open');await submitOrder();}catch(error){showAccountError('loginNotice',error.message);}});
            document.getElementById('forgotConsumerPassword').addEventListener('click',async()=>{const email=window.prompt('Informe o e-mail cadastrado para receber o link de redefinição:');if(!email)return;try{const data=await accountRequest(@json(route('public.consumer.password.email',['subdomain'=>$venue->subdomain])),{email},'loginNotice');showAccountError('loginNotice',data.message);document.getElementById('loginNotice').className='notice';}catch(error){showAccountError('loginNotice',error.message);}});
            const postalCode = document.getElementById('postalCode');
            if (postalCode) postalCode.addEventListener('input', () => lookupCep(postalCode,{street:'street',neighborhood:'neighborhood',city:'city',state:'state'}));
            async function submitOrder() {
                checkout.disabled = true; notice.style.display = 'none';
                try {
                    @if($venue->geofence_enabled)
                    if (!coordinates) coordinates = await new Promise((resolve, reject) => navigator.geolocation ? navigator.geolocation.getCurrentPosition(p => resolve({latitude:p.coords.latitude,longitude:p.coords.longitude,location_accuracy:p.coords.accuracy}), () => reject(new Error('Autorize a localização para pedir nesta mesa.')), {enableHighAccuracy:true,timeout:12000,maximumAge:30000}) : reject(new Error('Seu navegador não oferece localização.')));
                    @endif
                    const phone = document.getElementById('customerPhone').value;
                    const consent = document.getElementById('whatsappConsent').checked;
                    if (consent && !phone.trim()) throw new Error('Informe o WhatsApp para receber atualizações.');
                    const payload = {...coordinates, channel:channel?.value, customer_name:document.getElementById('customerName').value, customer_phone:phone, whatsapp_consent:consent, payment_method:document.getElementById('paymentMethod')?.value, change_for:document.getElementById('changeFor')?.value||null, coupon_code:document.getElementById('couponCode')?.value||null, delivery_zone_id:document.getElementById('deliveryZone')?.value||null, postal_code:postalCode?.value, street:document.getElementById('street')?.value, number:document.getElementById('number')?.value, complement:document.getElementById('complement')?.value, neighborhood:document.getElementById('neighborhood')?.value, city:document.getElementById('city')?.value, state:document.getElementById('state')?.value, reference:document.getElementById('reference')?.value, notes:document.getElementById('orderNotes').value, items:[...cart.values()].map(item => ({product_id:item.id, quantity:item.quantity, option_ids:item.optionIds}))};
                    const response = await fetch(@json($orderEndpoint), {method:'POST', headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content}, body:JSON.stringify(payload)});
                    const data = await response.json(); if (!response.ok) throw new Error(Object.values(data.errors||{})[0]?.[0] || data.message || 'Não foi possível enviar o pedido. Tente novamente.');
                    cart.clear(); render(); panel.classList.remove('open'); checkout.disabled = false; checkout.textContent = 'Enviar pedido';
                    if (data.tracking_url) { document.getElementById('trackOrderLink').href = data.tracking_url; document.getElementById('orderSuccessPanel').classList.add('open'); }
                } catch (error) { notice.className = 'notice error'; notice.textContent = error.message; notice.style.display = 'block'; checkout.disabled = false; }
            }
            checkout.addEventListener('click', async () => { if (!consumer) { checkout.disabled=false; accountPanel.classList.add('open'); return; } await submitOrder(); });
            if (consumer) hydrateConsumer(consumer);
            render();
            document.getElementById('continueShopping').addEventListener('click',()=>document.getElementById('orderSuccessPanel').classList.remove('open'));
            if ('serviceWorker' in navigator) { let reloading=false; const updateBox=document.getElementById('pwaUpdate'); const showUpdate=registration=>{updateBox.hidden=false;document.getElementById('pwaRefresh').onclick=()=>registration.waiting?.postMessage({type:'ATIVAR_ATUALIZACAO'});}; navigator.serviceWorker.register('{{ route('public.service-worker', ['subdomain' => $venue->subdomain]) }}',{scope:'/'}).then(registration=>{if(registration.waiting)showUpdate(registration);registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)showUpdate(registration);});});setInterval(()=>registration.update(),300000);});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!reloading){reloading=true;location.reload();}}); }
        })();
    </script>
@endif
<div id="pwaUpdate" hidden style="position:fixed;z-index:40;right:16px;bottom:18px;max-width:360px;border-radius:16px;background:#102b3c;color:#fff;padding:16px;box-shadow:0 18px 45px #10212b55"><strong>Uma versão nova está disponível.</strong><span style="display:block;margin-top:4px;color:#d8eee7;font-size:14px">Atualize para receber as melhorias mais recentes.</span><button id="pwaRefresh" type="button" style="margin-top:12px;border:0;border-radius:9px;background:var(--brand);color:#fff;padding:9px 14px;font:inherit;font-weight:800;cursor:pointer">Atualizar</button></div>
</body>
</html>
